178	import { DOCUMENT } from '@angular/common';
179	import { computed, inject, Injectable, signal, DestroyRef } from '@angular/core';
180	import { toSignal } from '@angular/core/rxjs-interop';
181	import { NavigationEnd, Router } from '@angular/router';
182	import { filter, map } from 'rxjs';
183	
184	export type Theme = 'light' | 'dark';
185	
186	export const DESTINATIONS = [
187	  { path: 'dashboard', label: 'Dashboard', icon: 'lucideLayoutDashboard' },
188	  { path: 'roster', label: 'Roster', icon: 'lucideUsers' },
189	  { path: 'missions', label: 'Missions', icon: 'lucideTarget' },
190	  { path: 'threats', label: 'Threats', icon: 'lucideShieldAlert' },
191	  { path: 'recruit', label: 'Recruit', icon: 'lucideUserPlus' },
192	  { path: 'settings', label: 'Settings', icon: 'lucideSettings' },
193	] as const;
194	
195	// Hero detail is reached from the roster, so it has a crumb but no rail entry.
196	const PAGE_TITLES: Readonly<Record<string, string>> = {
197	  dashboard: 'Dashboard',
198	  roster: 'Roster',
199	  detail: 'Hero detail',
200	  missions: 'Missions',
201	  recruit: 'Recruit',
202	  threats: 'Threats',
203	  settings: 'Settings',
204	};
205	
206	const THEME_KEY = 'hero-ops-theme';
207	const DARK_QUERY = '(prefers-color-scheme: dark)';
208	
209	// Component-scoped: provided by App, so each app instance owns its own theme state.
210	@Injectable()
211	export class AppViewModel {
212	  private readonly document = inject(DOCUMENT);
213	  private readonly router = inject(Router);
214	  private readonly window = this.document.defaultView;
215	
216	  readonly destinations = DESTINATIONS;
217	
218	  // A stored choice wins; with no choice the system preference decides.
219	  private hasChoice = this.storedTheme() !== null;
220	  readonly theme = signal<Theme>(this.storedTheme() ?? this.systemTheme());
221	  readonly isDark = computed(() => this.theme() === 'dark');
222	
223	  private readonly url = toSignal(
224	    this.router.events.pipe(
225	      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
226	      map((event) => event.urlAfterRedirects),
227	    ),
228	    { initialValue: this.router.url },
229	  );
230	
231	  readonly currentPage = computed(() => PAGE_TITLES[this.url().split('/')[1] ?? ''] ?? 'Hero Ops Console');
232	
233	  constructor() {
234	    this.applyTheme(this.theme());
235	
236	    const media = this.window?.matchMedia?.(DARK_QUERY);
237	    const onSystemChange = (event: MediaQueryListEvent) => {
238	      if (!this.hasChoice) this.applyTheme(event.matches ? 'dark' : 'light');
239	    };
240	    media?.addEventListener('change', onSystemChange);
241	    inject(DestroyRef).onDestroy(() => media?.removeEventListener('change', onSystemChange));
242	  }
243	
244	  toggleTheme(): void {
245	    const next: Theme = this.isDark() ? 'light' : 'dark';
246	    this.hasChoice = true;
247	    this.storeTheme(next);
248	    this.applyTheme(next);
249	  }
250	
251	  private applyTheme(theme: Theme): void {
252	    this.theme.set(theme);
253	    this.document.documentElement.classList.toggle('dark', theme === 'dark');
254	  }
255	
256	  private systemTheme(): Theme {
257	    return this.window?.matchMedia?.(DARK_QUERY).matches ? 'dark' : 'light';
258	  }
259	
260	  private storedTheme(): Theme | null {
261	    try {
262	      const value = this.window?.localStorage.getItem(THEME_KEY);
263	      return value === 'light' || value === 'dark' ? value : null;
264	    } catch {
265	      // Storage can be blocked; fall back to the system preference.
266	      return null;
267	    }
268	  }
269	
270	  private storeTheme(theme: Theme): void {
271	    try {
272	      this.window?.localStorage.setItem(THEME_KEY, theme);
273	    } catch {
274	      // Unpersisted for this session is acceptable when storage is blocked.
275	    }
276	  }
277	}
