362	export interface DashboardStat {
363	  readonly label: string;
364	  readonly value: number;
365	  readonly hint: string;
366	  readonly icon: 'lucideUserCheck' | 'lucideActivity' | 'lucideZap' | 'lucideShieldAlert';
