369	// Component-scoped: provided by Dashboard, so each visit gets a fresh derivation over the roster.
370	@Injectable()
371	export class DashboardViewModel {
372	  private readonly heroService = inject(HeroService);
373	
374	  readonly rosterCount = computed(() => this.heroService.heroes().length);
375	
376	  /** Highest power index first. Sorts a copy so the service's roster is never reordered. */
377	  readonly topHeroes = computed(() =>
378	    [...this.heroService.heroes()].sort((a, b) => b.power - a.power).slice(0, TOP_HERO_COUNT),
379	  );
380	
381	  readonly stats = computed<readonly DashboardStat[]>(() => {
382	    const heroes = this.heroService.heroes();
383	    const count = heroes.length;
384	    const active = heroes.filter((hero) => hero.status === 'Active').length;
385	    const injured = heroes.filter((hero) => hero.status === 'Injured').length;
386	    const mia = heroes.filter((hero) => hero.status === 'MIA').length;
387	    const missions = heroes.reduce((total, hero) => total + hero.missions, 0);
388	    const averagePower = count === 0 ? 0 : Math.round(heroes.reduce((total, hero) => total + hero.power, 0) / count);
389	
390	    return [
391	      { label: 'Heroes on roster', value: count, hint: `${active} active`, icon: 'lucideUserCheck' },
392	      { label: 'Missions on record', value: missions, hint: 'Across the roster', icon: 'lucideActivity' },
393	      { label: 'Average power', value: averagePower, hint: 'Index, 0-100', icon: 'lucideZap' },
394	      { label: 'MIA heroes', value: mia, hint: `${injured} injured`, icon: 'lucideShieldAlert' },
395	    ];
