427	import { Service, signal } from '@angular/core';
428	import { EXAMPLE_HEROES } from './hero.example-data';
429	import type { Hero } from './hero.model';
430	
431	/** The editable fields of a hero. The id is fixed once the record exists. */
432	export type HeroChanges = Partial<Omit<Hero, 'id'>>;
433	
434	/**
435	 * Holds the hero roster as in-memory signal state. There is no backend: the roster is
436	 * seeded from `EXAMPLE_HEROES` (example data) and resets on every page load.
437	 */
438	@Service()
439	export class HeroService {
440	  private readonly roster = signal<readonly Hero[]>(EXAMPLE_HEROES);
441	
442	  /** The whole roster, read-only. Derive views from it with `computed()` in a ViewModel. */
443	  readonly heroes = this.roster.asReadonly();
444	
