          <app-stat-tile [label]="stat.label" [value]="stat.value" [hint]="stat.hint">
            <ng-icon statIcon [name]="stat.icon" />
          </app-stat-tile>
        }
      </div>

      <section aria-labelledby="top-heroes-heading" class="flex flex-col gap-4">
