import { join } from 'node:path';
import { serveStatic, launchChromium } from './harness/playwright/serve-and-visit.mjs';
import { assertResponsive } from './harness/gate/check-responsive.mjs';

const DIST = join(process.cwd(), 'dist', 'angular-jig', 'browser');
const routes = [
  ['dashboard', 'app-dashboard'],
  ['roster', 'app-heroes'],
  ['detail/HRO-0007', 'app-hero-detail'],
  ['detail/11', 'app-hero-detail'],
  ['missions', 'app-missions'],
  ['threats', 'app-threats'],
  ['recruit', 'app-recruit'],
  ['settings', 'app-settings'],
];

const srv = await serveStatic(DIST, { spaFallback: true });
const browser = await launchChromium();
try {
  for (const [route, anchorSelector] of routes) {
    const { failures } = await assertResponsive({ origin: srv.origin, route, anchorSelector, browser });
    console.log(route, failures.length === 0 ? 'OK' : JSON.stringify(failures, null, 1));
  }
} finally {
  await browser.close();
  await srv.close();
}

